const e={meta:{title:"POP · Das SaaS für UEFN-Creator"},nav:{features:"Funktionen",pricing:"Preise",faq:"FAQ",login:"Anmelden",join:"Zur Beta",home:"POP, Startseite",lang:"Sprache",search:"Land suchen"},menu:{groups:["Organisieren","UEFN verbinden","Deine Map wachsen lassen"],items:[{t:"Aufgaben und Planung",d:"Einstündige Aufgaben, Meilensteine, Verzug im Blick."},{t:"Seiten",d:"Docs, Regeln und Datenbanken der Map."},{t:"Whiteboard",d:"Notizen, Formen und Pfeile, live im Team."},{t:"Team und Rollen",d:"Einladen, Rollen vergeben, jeder weiß, was zu tun ist."},{t:"Organizer",d:"Die Akteure des Levels sortiert und gesammelt bearbeitet."},{t:"UEFN Link",d:"Deine UEFN-Projekte mit POP synchronisiert."},{t:"Verbundene KIs",d:"Claude, Cursor oder Codex arbeiten deine Aufgaben ab."},{t:"POP Forge",d:"Die Desktop-App, die in UEFN baut."},{t:"Marktanalyse",d:"Genres, die Spieler anziehen, und gesättigte Genres."},{t:"Video-Trends",d:"Was auf TikTok und YouTube Shorts gerade läuft."},{t:"Playtests und Release",d:"Lass die Map testen und bereite den Start vor."},{t:"Auszahlungen",d:"Umsatzaufteilung und Abrechnung für jeden."}],bottom:["Discord und GitHub verbunden","Auf Mac und PC"],all:"Alle Funktionen"},hero:{announce:"Private Beta für UEFN-Creator geöffnet",h1a:"Erschaffe in UEFN.",h1b:"Allein oder im Team, ohne Chaos.",subA:"POP ist das SaaS, das UEFN-Creatorn von der Idee bis zum Release hilft: ",subB:"einstündige Aufgaben",subC:", Whiteboard, verbundene KIs, Marktanalyse und Umsatzaufteilung.",cta:"Auf die Warteliste",see:"Funktionen ansehen",micro1:"Private Beta",micro2:"Zugang über Warteliste",micro3:"Mit UEFN verbunden"},marquee:{label:"Funktioniert mit deinen Tools",epic:"Fortnite-API von Epic"},pain:{eyebrow:"Das Problem",h2a:"Discord, Google Docs, Dateien überall…",h2b:"und die Map kommt nicht voran.",without:"Ohne POP",with:"Mit POP",bad:["„Wer hat den Spawner angefasst?“","Ideen gehen im Discord verloren","Eine Aufgabenliste in einem Google Doc","Die Umsatztabelle, Version 7","„Wann releasen wir nochmal?“","Bauen, ohne zu wissen, ob das Genre läuft"],good:["Jede Aktion wird protokolliert und ist rückgängig machbar","Ideen vom Whiteboard werden zu Aufgaben","Einstündige Aufgaben mit Abhängigkeiten","Eine klare Abrechnung für alle","Meilensteine und Verzug werden automatisch verfolgt","Ein Urteil pro Genre, mit echten Zahlen"]},feat:{eyebrow:"Funktionen",h2:"Alles, um in UEFN zu erschaffen – von der Idee bis zum Release.",p:"Was du hier siehst, sind die echten Bildschirme von POP, vereinfacht.",items:[{tag:"Aufgaben und Planung",h:"Einstündige Aufgaben. Eine Planung, die hält.",p:"Der Generator teilt deine Map in einstündige Aufgaben mit Abhängigkeiten. Die Planung verfolgt Meilensteine und meldet Verzug, und ein integrierter Assistent fasst den Tag zusammen.",pts:["Kanban und Abhängigkeiten","Meilensteine und Verzug im Blick","Tageszusammenfassung"]},{tag:"Organizer",h:"Alle deine Geräte. In drei Sekunden sortiert.",p:"Suche nach Tag, Typ oder Ordner, wähle zwanzig aus und benenne sie um, verschiebe oder dupliziere sie auf einmal. Strg+Z macht rückgängig. Ist UEFN geschlossen, warten die Änderungen.",pts:["Suche tag:, type:, ordner:","Massenbearbeitung","Alles rückgängig machbar"]},{tag:"Whiteboard",h:"Zeichnet die Map gemeinsam.",p:"Haftnotizen, Formen, Pfeile, Farben, fett, unterstrichen: alles, um Ideen festzuhalten. Stimmt ab und macht aus den besten Notizen Aufgaben.",pts:["Volle Formatierung","Echtzeit im Team","Notizen → Aufgaben"]},{tag:"Analyse",h:"Wisse, was du baust, bevor du baust.",p:"Welche Genres Spieler anziehen, wo Platz ist, welche Maps zum Release abheben und was im Video gerade angesagt ist. Zahlen aus der offiziellen API von Epic.",pts:["Urteil pro Genre","Maps, die laufen","TikTok- und Shorts-Trends"]},{tag:"Auszahlungen",h:"Jeder weiß, was er bekommt.",p:"Aufteilungsregeln nach Prozent, Fixbetrag oder pro Aufgabe, Umsatzimport, Abrechnung pro Person. Schluss mit der Tabelle, die in Discord verloren geht.",pts:["Prozent, fix, pro Aufgabe","CSV-Import","Abrechnung für jeden"]}],aiB:"Du nutzt schon eine KI?",aiText:"Verbinde Claude, Cursor, Codex oder eine andere MCP-kompatible KI: Sie übernimmt eine Aufgabe, schreibt das Verse, kompiliert und schließt die Aufgabe mit einer Notiz. Jede Aktion wird protokolliert und ist rückgängig machbar. Kompatibel: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI."},stats:[["1 Std.","pro Aufgabe, um jeden Tag voranzukommen"],["0","externe KI-Dienste nötig"],["7 Tage","Statistiken pro Map, aus der API von Epic"],["100 %","der UEFN-Aktionen rückgängig machbar"]],pricing:{eyebrow:"Preise",h2:"Wähle deinen Plan.",p:"POP ist in der privaten Beta: Zugang über die Warteliste. Zum Start beginnt jedes Konto mit 7 Tagen kostenlosem Pro-Test, ohne Karte.",perMonth:"/ Monat",compare:"Pläne vergleichen",unlimited:"Unbegrenzt",soon:"Bald",plans:[{name:"Starter",tag:"Zum Erstellen",desc:"Der komplette Arbeitsbereich für deine Maps, allein oder im Team.",cta:"Auf die Liste"},{name:"Pro",tag:"Am vollständigsten",desc:"Alles aus Starter, plus Analyse: Map-Ideen, Markt, Discover-Tracking.",cta:"Auf die Liste"}],rows:["Organisation","Einstündige Aufgaben, Kanban, Abhängigkeiten","Integrierter Assistent (Tageszusammenfassung, Verzug)","Seiten, Whiteboard, Planung und Meilensteine","Maps","Mitglieder","UEFN","UEFN Link: synchronisierte Projekte","Actor-Organizer und Massenbearbeitung","Verbundene KIs (Claude, Cursor, Codex…)","POP Forge: unterstütztes Bauen in UEFN","Wachstum","Map-Ideen, Marktanalyse, Discover-Tracking","Videotrends TikTok und YouTube Shorts","Playtest-Austausch und Release-Tag","Umsatzaufteilung und Abrechnungen","Discord, GitHub, Lore"],perDay:["Weniger als 0,50 € pro Tag","Weniger als 1 € pro Tag"],hints:["","Deine Map in einstündige Aufgaben aufgeteilt, mit dem, was was blockiert","Jeden Morgen: was im Verzug ist und womit du anfängst","Map-Doku, Ideen in Echtzeit und der Kalender","So viele Maps, wie du willst","Lade das ganze Team ohne Aufpreis ein","","Deine KIs sehen das echte UEFN-Projekt: Akteure und Verse","","Verbinde deine KI per MCP; jede Aktion ist rückgängig zu machen","In UEFN bauen aus einer einfachen Anfrage","","Genres, die Spieler anziehen, und wo noch Platz ist","Was gerade auf TikTok und YouTube Shorts steigt","Tester finden und den Launch-Tag vorbereiten","Wer wie viel bekommt, mit einer Abrechnung für jeden","Benachrichtigungen und Links zu deinen Tools"]},faq:{eyebrow:"FAQ",h2:"Fragen, die uns gestellt werden.",items:[["Brauche ich einen Windows-PC?","Um UEFN zu verbinden, ja: UEFN läuft nur unter Windows, und UEFN Link läuft auf diesem PC. Der Rest von POP funktioniert in jedem Browser, auch auf dem Mac."],["Veröffentlicht POP meine Map?","Nein. POP bereitet alles vor (Prüfung vor der Veröffentlichung, Playtests, Plan für den Release-Tag), veröffentlicht wird aber immer im Creator-Portal von Epic."],["Funktioniert POP auch, wenn ich allein erstelle?","Ja. POP ist ab dem Starter-Plan für Solo-Creator und Teams gemacht: Du kannst später Mitglieder einladen, ohne etwas zu ändern."],["Welche KIs kann ich verbinden?","Alle, die MCP-Server unterstützen: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI. Claude Desktop setzt voraus, dass POP per HTTPS online ist. Das Abo deiner KI ist nicht in POP enthalten. Chat-KIs im Browser (ChatGPT, Gemini, Copilot im Web) werden vorerst nicht unterstützt. Einmal unter „Verbundene KIs“ verbunden, liest und bearbeitet deine KI Aufgaben und UEFN-Akteure, schreibt Verse, und jede Aktion wird protokolliert und lässt sich rückgängig machen."],["Woher kommen die Zahlen der Analyse?","Aus der offiziellen Fortnite-API von Epic: Spieler, Spitzenwert gleichzeitiger Spieler, Spielzeit und Bindung jeder öffentlichen Map über 7 Tage."],["Wie bekomme ich Zugang?","POP ist in einer geschlossenen Beta. Trag dich in die Warteliste ein: Wir prüfen die Anfragen einzeln und schicken dir dann deinen Benutzernamen und ein vorläufiges Passwort, das du beim ersten Login änderst."],["Was kostet es?","Die Preise stehen weiter oben. Sie gelten ab dem Start von POP; Beta-Mitglieder werden vor jeder Zahlung informiert."]]},final:{h2a:"Deine nächste Map",h2b:"beginnt hier.",p:"Trag dich in die Warteliste ein: Wir schicken dir den Zugang, sobald ein Platz frei wird."},foot:{legalTitle:"Rechtliches",made:"Von Fortnite-Creatorn für Fortnite-Creator gemacht.",legal:"Fortnite und UEFN sind Marken von Epic Games. POP ist weder mit Epic Games verbunden noch von Epic Games unterstützt.",product:"Produkt",help:"Hilfe",account:"Konto"},mock:{overview:"Übersicht",nav:["Übersicht","Seiten","Whiteboard","Aufgaben","Organizer","Markt"],hello:"Hallo Léa, ich schlage vor, mit #42 anzufangen.",late:"2 Aufgaben im Verzug (die älteste war für den 12. Nov. geplant).",mile:"Meilenstein „Beta“ in 5 Tagen: noch 9 Aufgaben, erwarteter Verzug 1 Tag.",take:"Übernehmen",start:"Starten",unlocks:"schaltet 3 andere Aufgaben frei",today:"heute geplant",waits:"wartet auf #42",todo:"Offen",doing:"In Arbeit",done:"Erledigt",tasks:["Punktesystem","Kulisse Zone 2","Endbildschirm","Interner Playtest","Spieler-Spawn","Sturm"],sent:"an UEFN gesendet",err:"Zeile 12: int und float können nicht addiert werden.",fix:"Korrigieren: Points += 1",red:"Team Rot",selected:"2 ausgewählt",rename:"Umbenennen",move:"Verschieben",dup:"Duplizieren",s1:"Teammodus 4v4",s2a:"Endboss",s2b:"in der Mitte",s3:"Wirtschaft: 1 Münze / Eliminierung",verdicts:["Gute Chance","Beliebt, aber umkämpft","Gesättigt","Nische"],typical:"Spieler / typische Map",earnings:"Einnahmen Oktober",roles:["Code · 40 %","Map · 35 %","Musik · fix","Rest"],noTransfer:"POP rechnet, überweist aber nichts."},wl:{eyebrow:"Private Beta",title:"Auf die Warteliste",intro:"Wir öffnen POP schrittweise, um jeden Creator gut zu begleiten. Sag uns, wer du bist, und wir schicken dir so bald wie möglich deinen Zugang.",pageIntro:"Während der Beta legt das Team die POP-Konten an. Sag uns, wer du bist: Sobald dein Zugang freigegeben ist, bekommst du deinen Benutzernamen und ein vorläufiges Passwort.",invalid:"Dieser Zugangslink ist ungültig, schon benutzt oder abgelaufen. Frag erneut an oder schreib dem POP-Team.",name:"Name oder Nickname",email:"E-Mail",studio:"Studio",optional:"(optional)",studioPh:"Name des Studios",team:"Teamgröße",teams:["Allein","2 bis 3","4 bis 10","Mehr als 10"],exp:"Erfahrung",exps:["UEFN-Einsteiger","Einige veröffentlichte Maps","Erfahrener Creator","Professionelles Studio"],links:"Deine Maps oder Kanäle",linksPh:"Insel-Codes, TikTok, YouTube…",msg:"Was du mit POP vorhast",msgPh:"Z. B.: Wir sind zu viert an einer Tycoon-Map und verlieren uns zwischen Discord und Google Docs.",send:"Zugang anfragen",sending:"Wird gesendet…",nospam:"Kein Spam: Wir schreiben dir nur, um dir Zugang zu geben.",privacy:"Datenschutzerklärung",okTitle:"Notiert, danke!",okText:"Sobald dein Zugang bereit ist, erhältst du eine E-Mail an die angegebene Adresse mit einem Link zur Aktivierung deines Kontos. Schau auch im Spam-Ordner nach.",alreadyTitle:"Du stehst schon auf der Liste.",approvedTitle:"Dein Zugang ist schon freigegeben.",approvedText:"Dein Konto ist bereit: Du hast eine E-Mail mit einem Link erhalten, um es zu aktivieren und dein Passwort zu wählen. Schau auch im Spam-Ordner nach.",close:"Schließen"}};export{e as default};
